$customers=$db->query("SELECT id_pelanggan,no_member,rfid_uid,nama_pelanggan FROM tbl_pelanggan WHERE status_member='aktif' ORDER BY nama_pelanggan")->fetchAll();
$qrisPointer=__DIR__.'/../uploads/qris/current.txt';
